import { useAuthStore } from '@/stores/authStore'
import { makeRedirectUri } from 'expo-auth-session'
import * as WebBrowser from 'expo-web-browser'
import * as AppleAuthentication from 'expo-apple-authentication'
import { Platform } from 'react-native'
import { redirectAfterAuth } from '@/utils/redirect-after-auth'

WebBrowser.maybeCompleteAuthSession()

const redirectUri = makeRedirectUri()

export const useAppleOAuth = () => {
	const { setAuth } = useAuthStore()

	const clientId = process.env.EXPO_PUBLIC_APPLE_CLIENT_ID
	if (!clientId) {
		throw new Error('Apple Client ID is not configured.')
	}

	const browserAppleSignIn = async () => {
		const params = new URLSearchParams({
			client_id: clientId,
			redirect_uri: `${process.env.EXPO_PUBLIC_WEB_URL}/api/oauth/apple`,
			response_type: 'code',
			scope: 'name email',
			response_mode: 'form_post',
			state: JSON.stringify({
				overrideRedirectUri: redirectUri
			})
		})

		const result = await WebBrowser.openAuthSessionAsync(
			`https://appleid.apple.com/auth/authorize?${params.toString()}`,
			redirectUri
		)
		if (result.type === 'success') {
			const url = new URL(result.url)
			const accessToken = url.searchParams.get('token')
			const refreshToken = url.searchParams.get('refreshToken')
			if (accessToken && refreshToken) {
				setAuth({
					accessToken,
					refreshToken
				})
				await redirectAfterAuth()
			}
		}
	}
	const nativeAppleSignIn = async () => {
		try {
			const credential = await AppleAuthentication.signInAsync({
				requestedScopes: [
					AppleAuthentication.AppleAuthenticationScope.FULL_NAME,
					AppleAuthentication.AppleAuthenticationScope.EMAIL
				]
			})
			if ('identityToken' in credential) {
				const identityToken = credential.identityToken
				const response = await fetch(
					`${process.env.EXPO_PUBLIC_CREATE_API_URL}/v0/auth/callback/apple/native`,
					{
						method: 'POST',
						headers: {
							'Content-Type': 'application/json'
						},
						body: JSON.stringify({ identityToken })
					}
				)
				const data = await response.json()
				if (data.accessToken && data.refreshToken) {
					setAuth({
						accessToken: data.accessToken,
						refreshToken: data.refreshToken
					})
					await redirectAfterAuth()
				}
			}
		} catch (error) {
			console.warn(error)
		}
	}
	return Platform.OS === 'ios' ? nativeAppleSignIn : browserAppleSignIn
}
